### Полный код класса `ClientHandler`

```java
package ru.otus.java.basic;

import ru.otus.java.basic.model.Role;
import ru.otus.java.basic.service.UserService;

import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.net.Socket;

public class ClientHandler {
    private final Server server;
    private final Socket socket;
    private final DataInputStream in;
    private final DataOutputStream out;
    private String username;

    public ClientHandler(Server server, Socket socket) {
        this.server = server;
        this.socket = socket;
        this.in = new DataInputStream(socket.getInputStream());
        this.out = new DataOutputStream(socket.getOutputStream());

        new Thread(() -> {
            try {
                authenticate();
                readMessages();
            } catch (IOException e) {
                e.printStackTrace();
            } finally {
                closeConnection();
            }
        }).start();
    }

    private void authenticate() throws IOException {
        while (true) {
            String message = in.readUTF();
            if (message.startsWith("/auth ")) {
                String[] parts = message.split(" ", 3);
                if (parts.length == 3) {
                    String login = parts[1];
                    String password = parts[2];
                    if (server.getUserService().authenticate(this, login, password)) {
                        break;
                    }
                }
            } else if (message.startsWith("/reg ")) {
                String[] parts = message.split(" ", 4);
                if (parts.length == 4) {
                    String login = parts[1];
                    String password = parts[2];
                    String username = parts[3];
                    if (server.getUserService().registration(this, login, password, username)) {
                        break;
                    }
                }
            }
        }
    }

    private void readMessages() throws IOException {
        while (true) {
            String message = in.readUTF();
            handleMessage(message);
        }
    }

    public void handleMessage(String message) {
        if (server.getUserService().isUserBanned(username)) {
            sendMessage("Вы забанены и не можете отправлять сообщения.");
            return;
        }

        if (message.startsWith("/ban ")) {
            String[] parts = message.split(" ", 3);
            if (parts.length >= 2) {
                String userToBan = parts[1];
                Role role = server.getUserService().getUserRole(username);
                System.out.println("Проверка роли пользователя: " + role); // Отладочное сообщение
                if ("ADMIN".equals(role.getName())) {
                    long banDuration = parts.length == 3 ? Long.parseLong(parts[2]) : -1;
                    System.out.println("Блокировка пользователя: " + userToBan + " на " + banDuration + " минут"); // Отладочное сообщение
                    server.getUserService().banUser(userToBan, banDuration);
                } else {
                    sendMessage("У вас нет прав для выполнения этой команды.");
                }
            } else {
                sendMessage("Неправильный формат команды. Используйте: /ban <username> [duration_in_minutes]");
            }
        } else {
            // Обработка других сообщений
            server.broadcastMessage(username + ": " + message);
        }
    }

    public void sendMessage(String message) {
        try {
            out.writeUTF(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void closeConnection() {
        server.unsubscribe(this);
        try {
            in.close();
            out.close();
            socket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public String getUsername() {
        return username;
    }
}
```

### Проверка

После внесения этих изменений, запустите сервер и клиент, выполните команду `/ban` и проверьте, что забаненный пользователь не может отправлять сообщения.

