    private static final String USERS_QUERY = "SELECT * FROM chat.users";
    private static final String USER_ROLES_QUERY = """
            select r.id, r.name from chat.roles r
            join chat.users_to_roles ur ON r.id = ur.role_id
            WHERE user_id = ?
            ORDER BY id
            """;

    private static final String USER_DELETE_QUERY = "DELETE FROM chat.users u WHERE u.login = ?";
    private static final String USER_CREATE_QUERY = "INSERT INTO chat.users (id, login, password, username) VALUES (?, ?, ?, ?)";
    private static final String USER_ROLE_CREATE_QUERY = "INSERT INTO chat.users_to_roles (user_id, role_id) VALUES (?, ?)";

    private static final String IS_ADMIN_QUERY = """
            select count(1) from chat.roles r
            join chat.users_to_roles ur ON r.id = ur.role_id
            WHERE user_id = ? and r.name = 'ADMIN'
            """;

    private static final String CHECK_BAN_QUERY = "SELECT ban_end_time FROM chat.bans WHERE user_id = ?";

    private final Connection connection;
    private Server server;
    private List<User> allUsers;

    public UserServiceJdbcImpl(Server server) throws SQLException {
        this.server = server;
        this.allUsers = new ArrayList<>();
        connection = DriverManager.getConnection(DATABASE_URL, "postgres", "postgres123");
    }

    @Override
    public void initialize() {
        System.out.println("Сервис аутентификации запущен: Database режим");
    }

    @Override
    public List<User> getAll() {
        try (Statement statement = connection.createStatement()) {
            try (ResultSet resultSet = statement.executeQuery(USERS_QUERY)) {
                while (resultSet.next()) {
                    int id = resultSet.getInt("id");
                    String login = resultSet.getString(2);
                    String password = resultSet.getString(3);
                    String username = resultSet.getString(4);
                    User user = new User(id, login, password, username);
                    allUsers.add(user);
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
        try (PreparedStatement ps = connection.prepareStatement(USER_ROLES_QUERY)) {
            for (User user : allUsers) {
                ps.setInt(1, user.getId());
                List<Role> roles = new ArrayList<>();
                try (ResultSet resultSet = ps.executeQuery()) {
                    while (resultSet.next()) {
                        int id = resultSet.getInt("id");
                        String name = resultSet.getString(2);
                        Role role = new Role(id, name);
                        roles.add(role);
                    }
                    user.setRoles(roles);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return allUsers;
    }

    @Override
    public boolean isAdmin(int userId) {
        int flag = 0;
        try (PreparedStatement ps = connection.prepareStatement(IS_ADMIN_QUERY)) {
            ps.setInt(1, userId);
            try (ResultSet resultSet = ps.executeQuery()) {
                while (resultSet.next()) {
                    flag = resultSet.getInt(1);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return flag == 1;
    }

    @Override
    public boolean authenticate(ClientHandler clientHandler, String login, String password) {
        String authUsername = getUsernameByLoginAndPassword(login, password);
        if (authUsername == null) {
            clientHandler.sendMessage("Некорретный логин/пароль");
            return false;
        }
        if (server.isUsernameBusy(authUsername)) {
            clientHandler.sendMessage("Указанная учетная запись уже занята");
            return false;
        }
        clientHandler.setUsername(authUsername);
        server.subscribe(clientHandler);
        clientHandler.sendMessage("/authok " + authUsername);
        return true;
    }

    @Override
    public boolean registration(ClientHandler clientHandler, String login, String password, String username) {
        if (login.trim().length() < 3 || password.trim().length() < 6 || username.trim().length() < 1) {
            clientHandler.sendMessage("Логин 3+ символа, Пароль 6+ символов, Имя пользователя 1+ символ");
            return false;
        }
        if (isLoginAlreadyExist(login)) {
            clientHandler.sendMessage("Указанный логин уже занят");
            return false;
        }
        if (isUsernameAlreadyExist(username)) {
            clientHandler.sendMessage("Указанное имя пользователя уже занято");
            return false;
        }
        createUser(login, password, username);
        clientHandler.setUsername(username);
        server.subscribe(clientHandler);
        clientHandler.sendMessage("/regok " + username);
        return true;
    }

    @Override
    public boolean removeUserByLogin(String login) {
        boolean isRemoved = false;
        try (PreparedStatement ps = connection.prepareStatement(USER_DELETE_QUERY)) {
            ps.setString(1, login);
            int rowsAffected = ps.executeUpdate();
            if (rowsAffected > 0) {
                isRemoved = getAll().removeIf(user -> user.getLogin().equals(login));
            }
        } catch (SQLException ex) {
            throw new RuntimeException(ex);
        }
        return isRemoved;
    }

    @Override
    public Role getUserRole(String username) {
        for (User user : getAll()) {
            if (user.getUsername().equals(username)) {
                for (Role role : user.getRoles()) {
                    System.out.println("Роль пользователя: " + role); // Отладочное сообщение
                    return role;
                }
            }
        }
        return null;
    }

    @Override
    public void close() {
        try {
            connection.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private String getUsernameByLoginAndPassword(String login, String password) {
        for (User u : getAll()) {
            if (u.getLogin().equals(login) && u.getPassword().equals(password)) {
                return u.getUsername();
            }
        }
        return null;
    }

    private boolean isLoginAlreadyExist(String login) {
        for (User u : getAll()) {
            if (u.getLogin().equals(login)) {
                return true;
            }
        }
        return false;
    }

    private boolean isUsernameAlreadyExist(String username) {
        for (User u : getAll()) {
            if (u.getUsername().equals(username)) {
                return true;
            }
        }
        return false;
    }

    public void createUser(String login, String password, String username) {
        int randomId = new Random().nextInt(Integer.MAX_VALUE);

        try (PreparedStatement psUser = connection.prepareStatement(USER_CREATE_QUERY);
             PreparedStatement psRole = connection.prepareStatement(USER_ROLE_CREATE_QUERY)) {

            psUser.setInt(1, randomId);
            psUser.setString(2, login);
            psUser.setString(3, password);
            psUser.setString(4, username);
            int userRowsAffected = psUser.executeUpdate();

            if (userRowsAffected > 0) {
                int managerRoleId = 2;
                psRole.setInt(1, randomId);
                psRole.setInt(2, managerRoleId);
                psRole.executeUpdate();
            }
        } catch (SQLException ex) {
            throw new RuntimeException("Ошибка при создании пользователя", ex);
        }
    }

    @Override
    public void banUser(String username, long durationInMinutes) {
        int userId = getUserIdByUsername(username);
        if (userId == -1) {
            throw new IllegalArgumentException("Пользователь не найден");
        }

        LocalDateTime banEndTime = durationInMinutes > 0 ? LocalDateTime.now().plusMinutes(durationInMinutes) : LocalDateTime.MAX;
        Ban ban = new Ban(userId, banEndTime);
        System.out.println("Блокировка пользователя: " + ban); // Отладочное сообщение

        String upsertQuery = """
            INSERT INTO chat.bans (user_id, ban_end_time)
            VALUES (?, ?)
            ON CONFLICT (user_id)
            DO UPDATE SET ban_end_time = EXCLUDED.ban_end_time
        """;

        try (PreparedStatement ps = connection.prepareStatement(upsertQuery)) {
            ps.setInt(1, ban.getUserId());
            ps.setTimestamp(2, Timestamp.valueOf(ban.getBanEndTime()));
            ps.executeUpdate();
        } catch (SQLException ex) {
            throw new RuntimeException("Ошибка при блокировке пользователя", ex);
        }
    }

    @Override
    public boolean isUserBanned(String username) {
        int userId = getUserIdByUsername(username);
        if (userId == -1) {
            return false;
        }

        try (PreparedStatement ps = connection.prepareStatement(CHECK_BAN_QUERY)) {
            ps.setInt(1, userId);
            try (ResultSet resultSet = ps.executeQuery()) {
                if (resultSet.next()) {
                    Timestamp banEndTime = resultSet.getTimestamp(1);
                    if (banEndTime != null && banEndTime.toLocalDateTime().isAfter(LocalDateTime.now())) {
                        return true;
                    }
                }
            }
        } catch (SQLException ex) {
            throw new RuntimeException("Ошибка при проверке блокировки пользователя", ex);
        }
        return false;
    }

    private int getUserIdByUsername(String username) {
        for (User user : getAll()) {
            if (user.getUsername().equals(username)) {
                System.out.println("ID пользователя: " + user.getId()); // Отладочное сообщение
                return user.getId();
            }
        }
        return -1;
    }
}
```

### Обновление класса `ClientHandler`

Теперь обновим класс `ClientHandler`, чтобы поддерживать команду для перманентного бана.

#### Обновленный класс `ClientHandler`:

```java
package ru.otus.java.basic;

import ru.otus.java.basic.model.Role;

import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.net.Socket;
import java.time.LocalDateTime;
import java.util.Timer;
import java.util.TimerTask;

public class ClientHandler {
    private Server server;
    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private String username;
    private LocalDateTime lastActivityTime;
    private Timer inactivityTimer;

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public ClientHandler(Server server, Socket socket) throws IOException {
        this.server = server;
        this.socket = socket;
        this.in = new DataInputStream(socket.getInputStream());
        this.out = new DataOutputStream(socket.getOutputStream());
        this.lastActivityTime = LocalDateTime.now();
        this.inactivityTimer = new Timer(true);
        startInactivityTimer();

        new Thread(() -> {
            try {
                System.out.println("Подключился новый клиент");
                while (true) {
                    lastActivityTime = LocalDateTime.now();
                    String message = in.readUTF();
                    if (message.equals("/exit")) {
                        sendMessage("/exitok");
                        return;
                    }
                    if (message.startsWith("/auth ")) {
                        String[] elements = message.split(" ");
                        if (elements.length != 3) {
                            sendMessage("Неверный формат команды /auth");
                            continue;
                        }
                        if (server.getUserService().authenticate(this, elements[1], elements[2])) {
                            break;
                        }
                        continue;
                    }
                    if (message.startsWith("/register ")) {
                        String[] elements = message.split(" ");
                        if (elements.length != 4) {
                            sendMessage("Неверный формат команды /register");
                            continue;
                        }
                        if (server.getUserService().registration(this, elements[1], elements[2], elements[3])) {
                            break;
                        }
                        continue;
                    }
                    sendMessage("Перед работой с чатом необходимо выполнить аутентификацию '/auth login password' или регистрацию '/register login password username'");
                }
                while (true) {
                    String message = in.readUTF();
                    lastActivityTime = LocalDateTime.now();
                    if (server.getUserService().isUserBanned(username)) {
                        sendMessage("Вы забанены и не можете отправлять сообщения.");
                        continue;
                    }
                    if (message.startsWith("/")) {
                        if (message.equals("/exit")) {
                            sendMessage("/exitok");
                            break;
                        } else if (message.startsWith("/w ")) {
                            String[] parts = message.split(" ", 3);
                            if (parts.length == 3) {
                                String recipient = parts[1];
                                String privateMessage = parts[2];
                                server.sendPrivateMessage(recipient, username + " (личное сообщение): " + privateMessage);
                            } else {
                                sendMessage("Неправильный формат личного сообщения. Используйте: /w <username> <message>");
                            }
                        } else if (message.startsWith("/kick ")) {
                            String[] parts = message.split(" ", 2);
                            if (parts.length == 2) {
                                String userToKick = parts[1];
                                Role role = server.getUserService().getUserRole(username);
                                if ("ADMIN".equals(role.getName())) {
                                    server.kickUser(userToKick);
                                } else {
                                    sendMessage("У вас нет прав для выполнения этой команды.");
                                }
                            } else {
                                sendMessage("Неправильный формат команды. Используйте: /kick <username>");
                            }
                        } else if (message.equals("/activelist")) {
                            sendMessage("Активные пользователи: " + String.join(", ", server.getActiveClients()));
                        } else if (message.startsWith("/ban ")) {
                            String[] parts = message.split(" ", 3);
                            if (parts.length >= 2) {
                                String userToBan = parts[1];
                                Role role = server.getUserService().getUserRole(username);
                                if ("ADMIN".equals(role.getName())) {
                                    long banDuration = parts.length == 3 ? Long.parseLong(parts[2]) : -1;
                                    server.getUserService().banUser(userToBan, banDuration);
                                } else {
                                    sendMessage("У вас нет прав для выполнения этой команды.");
                                }
                            } else {
                                sendMessage("Неправильный формат команды. Используйте: /ban <username> [duration_in_minutes]");
                            }
                        } else if (message.equals("/shutdown")) {
                            Role role = server.getUserService().getUserRole(username);
                            if ("ADMIN".equals(role.getName())) {
                                server.shutdown();
                            } else {
                                sendMessage("У вас нет прав для выполнения этой команды.");
                            }
                        }
                        continue;
                    }
                    server.broadcastMessage(username + ": " + message);
                }
            } catch (IOException e) {
                e.printStackTrace();
            } finally {
                disconnect();
            }
        }).start();
    }

    public void sendMessage(String message) {
        try {
            System.out.println("Отправка сообщения: " + message);
            out.writeUTF(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void disconnect() {
        server.unsubscribe(this);
        try {
            if (in != null) {
                in.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        try {
            if (out != null) {
                out.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        try {
            if (socket != null) {
                socket.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void startInactivityTimer() {
        inactivityTimer.schedule(new TimerTask() {
            @Override
            public void run() {
                if (LocalDateTime.now().minusMinutes(20).isAfter(lastActivityTime)) {
                    sendMessage("Вы были отключены из-за неактивности.");
                    disconnect();
                }
            }
        }, 0, 60 * 1000);
    }
}
```

### Проверка

После внесения этих изменений, запустите сервер и клиент, выполните команду `/ban <username>` для перманентного бана и `/ban <username> <duration_in_minutes>` для временного бана. Убедитесь, что перманентный бан работает корректно и пользователь не может отправлять сообщения.

Команда `/shutdown` должна корректно останавливать сервер, но, возможно, текущая реализация не завершает все потоки или не закрывает все ресурсы должным образом. Давайте убедимся, что команда `/shutdown` корректно завершает работу сервера и всех связанных ресурсов.

### Обновление метода `shutdown` в классе `Server`

Убедимся, что метод `shutdown` корректно завершает все потоки и закрывает все ресурсы.

#### Обновленный метод `shutdown`:

```java
public synchronized void shutdown() {
    running = false;
    for (ClientHandler client : clients) {
        client.sendMessage("Сервер остановлен.");
        client.disconnect();
    }
    try {
        if (userService != null) {
            userService.close();
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    System.out.println("Сервер остановлен.");
    System.exit(0);
}
```

