    }

    @Override
    public boolean isUserBanned(String username) {
        int userId = getUserIdByUsername(username);
        if (userId == -1) {
            return false;
        }

        try (PreparedStatement ps = connection.prepareStatement(CHECK_BAN_QUERY)) {
            ps.setInt(1, userId);
            try (ResultSet resultSet = ps.executeQuery()) {
                if (resultSet.next()) {
                    Timestamp banEndTime = resultSet.getTimestamp(1);
                    if (banEndTime != null && banEndTime.toLocalDateTime().isAfter(LocalDateTime.now())) {
                        return true;
                    }
                }
            }
        } catch (SQLException ex) {
            throw new RuntimeException("Ошибка при проверке блокировки пользователя", ex);
        }
        return false;
    }

    private int getUserIdByUsername(String username) {
        for (User user : getAll()) {
            if (user.getUsername().equals(username)) {
                System.out.println("ID пользователя: " + user.getId()); // Отладочное сообщение
                return user.getId();
            }
        }
        return -1;
    }
}
```

### Проверка

После внесения этих изменений, запустите сервер и клиент, выполните команду `/ban` и проверьте, что забаненный пользователь не может отправлять сообщения.
